1	-- Operation Empower B1.1 (forward-only): founder-controlled, versioned partner content.
2	-- An item is a stable identity whose audience never changes. A version is editable only while it is a draft; from
3	-- submission onwards it is immutable and moves only through the lifecycle below. Approval evidence is append-only.
4	-- Nothing here is served to partners: partner reads arrive in later phases behind their own switches.
5	--
6	--   draft -> in_review -> approved -> published -> superseded
7	--     |          |-> changes_requested     |
8	--     |          |-> archived (rejected)    |-> archived (withdrawn, reason required)
9	--     |-> archived                approved -> archived
10	CREATE TABLE empower_content_items (
11	 id uuid PRIMARY KEY,
12	 kind text NOT NULL CHECK (kind IN ('resource','lesson','knowledge','objection','template')),
13	 slug text NOT NULL UNIQUE CHECK (char_length(slug) BETWEEN 3 AND 120 AND slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
14	 audience text NOT NULL CHECK (audience IN ('partner_only','client_facing')),
15	 -- AP-GOV-06: commercial content is reviewed at least every 3 months, service content at least every 6.
16	 review_cadence_months smallint NOT NULL CHECK (review_cadence_months IN (3,6)),
17	 created_by uuid NOT NULL REFERENCES admin_users(id),
18	 created_at timestamptz NOT NULL DEFAULT now()
19	);
20	CREATE TRIGGER empower_content_items_immutable BEFORE UPDATE OR DELETE ON empower_content_items FOR EACH ROW EXECUTE FUNCTION commercial_history_immutable();
21	
22	CREATE TABLE empower_content_versions (
23	 id uuid PRIMARY KEY,
24	 item_id uuid NOT NULL REFERENCES empower_content_items(id),
25	 version integer NOT NULL CHECK (version > 0),
26	 title text NOT NULL CHECK (char_length(title) BETWEEN 3 AND 200),
27	 body text NOT NULL CHECK (char_length(body) <= 30000),
28	 fields jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(fields) = 'object'),
29	 source_refs jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(source_refs) = 'array' AND jsonb_array_length(source_refs) <= 30),
30	 change_summary text CHECK (change_summary IS NULL OR char_length(change_summary) <= 2000),
31	 lint_override_reason text CHECK (lint_override_reason IS NULL OR char_length(lint_override_reason) BETWEEN 10 AND 2000),
32	 status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','in_review','changes_requested','approved','published','superseded','archived')),
33	 submitted_by uuid REFERENCES admin_users(id),
34	 submitted_at timestamptz,
35	 review_by date,
36	 approved_at timestamptz,
37	 published_at timestamptz,
38	 superseded_at timestamptz,
39	 archived_at timestamptz,
40	 archive_reason text CHECK (archive_reason IS NULL OR char_length(archive_reason) BETWEEN 5 AND 2000),
41	 created_by uuid NOT NULL REFERENCES admin_users(id),
42	 created_at timestamptz NOT NULL DEFAULT now(),
43	 UNIQUE (item_id, version),
44	 CHECK (status IN ('draft','archived') OR (submitted_by IS NOT NULL AND submitted_at IS NOT NULL)),
45	 CHECK (status NOT IN ('approved','published','superseded') OR (review_by IS NOT NULL AND approved_at IS NOT NULL)),
46	 CHECK (status NOT IN ('published','superseded') OR published_at IS NOT NULL)
47	);
48	-- At most one published version per item, and at most one version in progress (draft, in review or approved).
49	CREATE UNIQUE INDEX empower_content_one_published ON empower_content_versions(item_id) WHERE status = 'published';
50	CREATE UNIQUE INDEX empower_content_one_open ON empower_content_versions(item_id) WHERE status IN ('draft','in_review','approved');
51	CREATE INDEX empower_content_versions_status ON empower_content_versions(status, review_by);
52	
53	CREATE TABLE empower_content_approvals (
54	 id uuid PRIMARY KEY,
55	 version_id uuid NOT NULL REFERENCES empower_content_versions(id),
56	 decision text NOT NULL CHECK (decision IN ('approved','changes_requested','rejected')),
57	 decided_by uuid NOT NULL REFERENCES admin_users(id),
58	 decided_at timestamptz NOT NULL DEFAULT now(),
59	 reference text NOT NULL CHECK (char_length(reference) BETWEEN 3 AND 200),
60	 notes text NOT NULL CHECK (char_length(notes) BETWEEN 5 AND 2000),
61	 review_by date,
62	 -- AP-GOV-04: an author approving their own version must record why (only permitted while a single founder is active).
63	 self_approval_reason text CHECK (self_approval_reason IS NULL OR char_length(self_approval_reason) BETWEEN 10 AND 2000),
64	 CHECK ((decision = 'approved') = (review_by IS NOT NULL)),
65	 CHECK (decision = 'approved' OR self_approval_reason IS NULL)
66	);
67	CREATE INDEX empower_content_approvals_version ON empower_content_approvals(version_id, decided_at);
68	CREATE TRIGGER empower_content_approvals_immutable BEFORE UPDATE OR DELETE ON empower_content_approvals FOR EACH ROW EXECUTE FUNCTION commercial_history_immutable();
