70	CREATE FUNCTION empower_content_approval_guard() RETURNS trigger LANGUAGE plpgsql AS $$
71	DECLARE v record;
72	BEGIN
73	  SELECT cv.status, cv.created_by, ci.review_cadence_months INTO v
74	    FROM empower_content_versions cv JOIN empower_content_items ci ON ci.id = cv.item_id WHERE cv.id = NEW.version_id FOR UPDATE OF cv;
75	  IF NOT FOUND OR v.status <> 'in_review' THEN RAISE EXCEPTION 'Only a version in review can receive a decision'; END IF;
76	  IF NEW.decision = 'approved' THEN
77	    IF NEW.decided_by = v.created_by AND NEW.self_approval_reason IS NULL THEN RAISE EXCEPTION 'An author approving their own version must record a reason'; END IF;
78	    IF NEW.decided_by <> v.created_by AND NEW.self_approval_reason IS NOT NULL THEN RAISE EXCEPTION 'A self-approval reason applies only to the author'; END IF;
79	    IF NEW.review_by <= (NEW.decided_at AT TIME ZONE 'UTC')::date
80	       OR NEW.review_by > ((NEW.decided_at AT TIME ZONE 'UTC') + make_interval(months => v.review_cadence_months))::date THEN
81	      RAISE EXCEPTION 'The review date must be in the future and within the review cadence for this content';
82	    END IF;
83	  END IF;
84	  RETURN NEW;
85	END $$;
86	CREATE TRIGGER empower_content_approval_guard BEFORE INSERT ON empower_content_approvals FOR EACH ROW EXECUTE FUNCTION empower_content_approval_guard();
