88	CREATE FUNCTION empower_content_lifecycle() RETURNS trigger LANGUAGE plpgsql AS $$
89	DECLARE decided record; moved boolean; expected text;
90	BEGIN
91	  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Content version history is retained'; END IF;
92	  IF TG_OP = 'INSERT' THEN
93	    IF NEW.status <> 'draft' OR NEW.submitted_by IS NOT NULL OR NEW.submitted_at IS NOT NULL OR NEW.review_by IS NOT NULL OR NEW.approved_at IS NOT NULL
94	       OR NEW.published_at IS NOT NULL OR NEW.superseded_at IS NOT NULL OR NEW.archived_at IS NOT NULL OR NEW.archive_reason IS NOT NULL THEN
95	      RAISE EXCEPTION 'A content version starts as a draft';
96	    END IF;
97	    RETURN NEW;
98	  END IF;
99	  IF NEW.id <> OLD.id OR NEW.item_id <> OLD.item_id OR NEW.version <> OLD.version OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at THEN
100	    RAISE EXCEPTION 'Content version identity is immutable';
101	  END IF;
102	  IF (NEW.title, NEW.body, NEW.fields, NEW.source_refs, NEW.change_summary, NEW.lint_override_reason)
103	     IS DISTINCT FROM (OLD.title, OLD.body, OLD.fields, OLD.source_refs, OLD.change_summary, OLD.lint_override_reason)
104	     AND NOT (OLD.status = 'draft' AND NEW.status = 'draft') THEN
105	    RAISE EXCEPTION 'Only a draft can be edited; submitted content is immutable';
106	  END IF;
107	  moved := NEW.status IS DISTINCT FROM OLD.status;
108	  IF NOT moved THEN
109	    IF (NEW.submitted_by, NEW.submitted_at, NEW.review_by, NEW.approved_at, NEW.published_at, NEW.superseded_at, NEW.archived_at, NEW.archive_reason)
110	       IS DISTINCT FROM (OLD.submitted_by, OLD.submitted_at, OLD.review_by, OLD.approved_at, OLD.published_at, OLD.superseded_at, OLD.archived_at, OLD.archive_reason) THEN
111	      RAISE EXCEPTION 'Lifecycle evidence changes only with a lifecycle transition';
112	    END IF;
113	    RETURN NEW;
114	  END IF;
115	  IF NOT ((OLD.status = 'draft' AND NEW.status IN ('in_review','archived'))
116	       OR (OLD.status = 'in_review' AND NEW.status IN ('approved','changes_requested','archived'))
117	       OR (OLD.status = 'approved' AND NEW.status IN ('published','archived'))
118	       OR (OLD.status = 'published' AND NEW.status IN ('superseded','archived'))) THEN
119	    RAISE EXCEPTION 'Invalid content lifecycle transition from % to %', OLD.status, NEW.status;
120	  END IF;
121	  -- Evidence already recorded never changes; each transition may only add its own.
122	  IF (OLD.submitted_by IS NOT NULL AND NEW.submitted_by IS DISTINCT FROM OLD.submitted_by) OR (OLD.submitted_at IS NOT NULL AND NEW.submitted_at IS DISTINCT FROM OLD.submitted_at)
123	     OR (OLD.review_by IS NOT NULL AND NEW.review_by IS DISTINCT FROM OLD.review_by) OR (OLD.approved_at IS NOT NULL AND NEW.approved_at IS DISTINCT FROM OLD.approved_at)
124	     OR (OLD.published_at IS NOT NULL AND NEW.published_at IS DISTINCT FROM OLD.published_at) THEN
125	    RAISE EXCEPTION 'Recorded lifecycle evidence is permanent';
126	  END IF;
127	  IF NEW.status <> 'in_review' AND OLD.status = 'draft' AND NEW.submitted_at IS NOT NULL THEN RAISE EXCEPTION 'Submission evidence belongs to submission'; END IF;
128	  IF NEW.status IN ('approved','changes_requested') OR (OLD.status = 'in_review' AND NEW.status = 'archived') THEN
129	    expected := CASE NEW.status WHEN 'approved' THEN 'approved' WHEN 'changes_requested' THEN 'changes_requested' ELSE 'rejected' END;
130	    SELECT decision, review_by INTO decided FROM empower_content_approvals WHERE version_id = NEW.id ORDER BY decided_at DESC, id DESC LIMIT 1;
131	    IF NOT FOUND OR decided.decision <> expected THEN
132	      RAISE EXCEPTION 'This transition needs a matching recorded founder decision';
133	    END IF;
134	    IF NEW.status = 'approved' AND (NEW.review_by IS DISTINCT FROM decided.review_by OR NEW.approved_at IS NULL) THEN
135	      RAISE EXCEPTION 'Approval must carry the recorded review date';
136	    END IF;
137	  ELSIF NEW.review_by IS DISTINCT FROM OLD.review_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN
138	    RAISE EXCEPTION 'Approval evidence belongs to approval';
139	  END IF;
140	  IF NEW.status = 'published' AND (NEW.published_at IS NULL OR NEW.review_by < (NEW.published_at AT TIME ZONE 'UTC')::date) THEN
141	    RAISE EXCEPTION 'Content past its review date cannot be published';
142	  END IF;
143	  IF NEW.status <> 'published' AND NEW.published_at IS DISTINCT FROM OLD.published_at THEN RAISE EXCEPTION 'Publication evidence belongs to publication'; END IF;
144	  IF NEW.status = 'superseded' AND NEW.superseded_at IS NULL THEN RAISE EXCEPTION 'Supersession needs a timestamp'; END IF;
145	  IF NEW.status = 'archived' AND NEW.archived_at IS NULL THEN RAISE EXCEPTION 'Archiving needs a timestamp'; END IF;
146	  IF NEW.status = 'archived' AND OLD.status = 'published' AND NEW.archive_reason IS NULL THEN RAISE EXCEPTION 'Withdrawing published content needs a recorded reason'; END IF;
147	  RETURN NEW;
148	END $$;
149	CREATE TRIGGER empower_content_lifecycle_guard BEFORE INSERT OR UPDATE OR DELETE ON empower_content_versions FOR EACH ROW EXECUTE FUNCTION empower_content_lifecycle();
